<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { api, setToken, stream } from './api'
import AuthPanel from './components/AuthPanel.vue'
import ArticleEditor from './components/ArticleEditor.vue'
import TopicReviewPanel from './components/TopicReviewPanel.vue'
import AssetGallery from './components/AssetGallery.vue'
import PerformanceFeedback from './components/PerformanceFeedback.vue'
import RatingPanel from './components/RatingPanel.vue'
import PromptLab from './components/PromptLab.vue'
import KnowledgePanel from './components/KnowledgePanel.vue'
import AccountPanel from './components/AccountPanel.vue'

const user = ref(null), ready = ref(false), screen = ref('workbench'), sessions = ref([]), task = ref(null)
const archived = ref(false), busy = ref(false), error = ref(''), info = ref(''), capabilities = ref({}), dashboard = ref({})
const selected = ref(''), streamingText = ref(''), stage = ref(''), timeline = ref([]), checkpoints = ref([]), metrics = ref({items:[],summary:{}})
const detailTab = ref('progress'), reviewers = ref([])
const form = ref({course_category:'AI应用开发',target_audience:'零基础、希望理解 AI 应用开发的学习者',brief:'',topic_count:4,card_count:4,theme:'clean',content_template:'tutorial',editor_notes:'',workflow_template:'xhs_wechat',reviewer_ids:[],review_topics:true})
const sourceText = ref(''), advanced = ref(false), rename = ref('')
const statusNames = {QUEUED:'等待执行',RUNNING:'正在生成',WAITING_TOPIC_SELECTION:'等待选题',WAITING_TOPIC_REVIEW:'等待选题审核',WAITING_ARTICLE_REVIEW:'等待审稿',READY:'图文就绪',FAILED:'需要处理'}
const nodeNames = {topics:'选题策划',write_article:'长文撰写',summarize:'卡片提炼',render_images:'图片生成',wechat_format:'公众号排版'}
const isRunning = computed(() => ['QUEUED','RUNNING'].includes(task.value?.status))
const currentStep = computed(() => { const s=task.value?.status; if(s==='READY')return 4;if(s==='WAITING_ARTICLE_REVIEW')return 2;if(['WAITING_TOPIC_SELECTION','WAITING_TOPIC_REVIEW'].includes(s))return 1;if(['summarize','render_images','wechat_format'].includes(stage.value))return 3;return s==='RUNNING'&&stage.value==='write_article'?2:0 })
const title = computed(() => ({library:'课程素材库',insights:'创作概览',prompts:'提示词与评测',account:'账号设置'}[screen.value]||task.value?.title||'开始一次有价值的创作'))
const canReview = computed(() => (task.value?.state.pending_review?.reviewer?.reviewer_id || task.value?.owner_id) === user.value?.id)
let controller = null, generation = 0
const cursors = new Map()

async function safe(action) { error.value='';try { return await action() } catch(e) { if(e.status===401&&user.value){ logout(false);error.value='登录已过期，请重新登录' }else error.value=e.message;return null } }
async function loadSessions(){ const data=await api(`/tasks?limit=100&archived=${archived.value}`);sessions.value=data.items;dashboard.value=await api('/dashboard') }
async function login(value){ user.value=value;await safe(async()=>{capabilities.value=await api('/capabilities');reviewers.value=await api('/reviewers');await loadSessions();const saved=sessionStorage.getItem(`active_${value.id}`);if(saved)await activate(saved)}) }
async function logout(remote=true){if(remote)try{await api('/auth/logout',{method:'POST'})}catch{}controller?.abort();generation++;setToken('');user.value=null;task.value=null;sessions.value=[];streamingText.value='';screen.value='workbench'}
function newTask(){controller?.abort();generation++;task.value=null;selected.value='';streamingText.value='';timeline.value=[];stage.value='';screen.value='workbench';error.value='';if(user.value)sessionStorage.removeItem(`active_${user.value.id}`)}
async function refreshDetails(id){ const [m,c]=await Promise.all([api(`/tasks/${id}/metrics`),api(`/tasks/${id}/checkpoints`)]);if(task.value?.id===id){metrics.value=m;checkpoints.value=c} }
async function activate(id){
  controller?.abort();generation++;screen.value='workbench';selected.value='';streamingText.value='';timeline.value=[];stage.value=''
  const value=await api(`/tasks/${id}`);task.value=value;rename.value=value.title;sessionStorage.setItem(`active_${user.value.id}`,id)
  await refreshDetails(id);if(['QUEUED','RUNNING'].includes(value.status))listen(id)
}
async function listen(id){
  controller?.abort();controller=new AbortController();const signal=controller.signal;const run=++generation
  for(let attempt=0;attempt<3&&!signal.aborted;attempt++){
    try{
      await stream(id,cursors.get(id)||0,event=>{
        if(run!==generation||task.value?.id!==id)return
        if(event.id)cursors.set(id,event.id)
        if(event.type==='article_delta'){streamingText.value=event.data.reset?event.data.text:streamingText.value+event.data.text}
        if(event.type==='node_started')stage.value=event.data.node
        if(['node_started','node_completed','failed','state_changed'].includes(event.type))timeline.value=[...timeline.value,event].slice(-16)
      },signal)
      if(signal.aborted||run!==generation)return
      task.value=await api(`/tasks/${id}`);await Promise.all([loadSessions(),refreshDetails(id)])
      if(!['QUEUED','RUNNING'].includes(task.value.status))return
    }catch(e){if(signal.aborted||run!==generation)return;if(attempt===2)info.value='进度连接暂时中断，正在读取已保存的状态。'}
    await new Promise(resolve=>setTimeout(resolve,700))
  }
  while(!signal.aborted&&run===generation){await new Promise(resolve=>setTimeout(resolve,1500));try{const value=await api(`/tasks/${id}`);if(run!==generation)return;task.value=value;if(!['QUEUED','RUNNING'].includes(value.status)){await loadSessions();await refreshDetails(id);return}}catch(e){if(e.status===401){logout(false);return}}}
}
async function create(){busy.value=true;await safe(async()=>{const value=await api('/tasks',{method:'POST',body:{...form.value,sources:sourceText.value.trim()?[{title:'本次参考资料',excerpt:sourceText.value.trim()}]:[]}});await activate(value.id);await loadSessions()});busy.value=false}
async function action(path,body={}){if(!task.value)return;busy.value=true;await safe(async()=>{await api(`/tasks/${task.value.id}/${path}`,{method:'POST',body});streamingText.value='';stage.value='';task.value={...task.value,status:'QUEUED'};listen(task.value.id);await loadSessions()});busy.value=false}
async function selectTopic(){await action('select-topic',{interrupt_id:task.value.interrupt_id,topic_id:selected.value,operator:user.value.username})}
async function review(decision,value){await action('review',{interrupt_id:task.value.interrupt_id,article_version:task.value.state.article_version,decision,operator:user.value.username,...(decision==='approved'?{edited_article:value}:{feedback:value})})}
async function saveName(){await safe(async()=>{task.value=await api(`/tasks/${task.value.id}`,{method:'PATCH',body:{title:rename.value}});await loadSessions();info.value='会话名称已保存'})}
async function archiveTask(value){await safe(async()=>{await api(`/tasks/${value.id}`,{method:'PATCH',body:{archived:!archived.value}});if(task.value?.id===value.id)newTask();await loadSessions()})}
async function forkCheckpoint(checkpoint){busy.value=true;await safe(async()=>{const value=await api(`/tasks/${task.value.id}/fork`,{method:'POST',body:{checkpoint_id:checkpoint.id}});await activate(value.id);await loadSessions()});busy.value=false}
async function refreshCurrent(){await safe(async()=>{if(task.value)await activate(task.value.id);else await loadSessions()})}
onMounted(async()=>{try{await login(await api('/auth/me'))}catch{}ready.value=true})
onBeforeUnmount(()=>{controller?.abort();generation++})
</script>

<template>
  <div v-if="!ready" class="initial-loading">正在打开本地工作台…</div>
  <AuthPanel v-else-if="!user" @login="login"/>
  <div v-else class="app-layout">
    <aside class="sidebar"><div class="brand"><span class="brand-mark">知</span><div>知行<span class="brand-sub">AI 内容工作台</span></div></div><button class="new-button" @click="newTask">＋ 新建创作</button><nav><button :class="{active:screen==='workbench'}" @click="screen='workbench'">◈ 创作工作台</button><button :class="{active:screen==='library'}" @click="screen='library'">▤ 课程素材库</button><button :class="{active:screen==='insights'}" @click="screen='insights';safe(loadSessions)">◷ 创作概览</button><button :class="{active:screen==='prompts'}" @click="screen='prompts'">◇ 提示词与评测</button><button :class="{active:screen==='account'}" @click="screen='account'">⚙ 账号设置</button></nav><div class="session-heading"><span>{{ archived?'已归档':'最近创作' }}</span><button class="sidebar-link" @click="archived=!archived;safe(loadSessions)">{{ archived?'返回':'归档' }}</button></div><div class="session-list"><div v-for="item in sessions" :key="item.id" :class="['session-item',{selected:task?.id===item.id&&screen==='workbench'}]"><button class="session-select" @click="safe(()=>activate(item.id))"><span>{{ item.session_title||item.title||'未命名创作' }}</span><small><i :class="['status-dot',item.status]"></i>{{ statusNames[item.status] }}</small></button><button v-if="item.owner_id===user.id" class="archive-button" :aria-label="archived?'恢复会话':'归档会话'" @click="archiveTask(item)">{{ archived?'↶':'⊟' }}</button></div><p v-if="!sessions.length" class="sidebar-empty">{{ archived?'暂无归档':'还没有创作记录' }}</p></div><div class="sidebar-bottom"><div class="avatar">{{ user.username.slice(0,1).toUpperCase() }}</div><div class="user-name">{{ user.username }}<small>本地工作空间</small></div><button aria-label="退出登录" @click="logout()">↪</button></div></aside>
    <main class="main"><header class="topbar"><div><span class="eyebrow">CONTENT OPERATIONS</span><h1>{{ title }}</h1></div><div class="header-actions"><span :class="['mode-badge',{demo:capabilities.demo_mode}]">{{ capabilities.demo_mode?'● 演示模型':'● 真实模型' }}</span><button @click="refreshCurrent">刷新</button><a href="/docs" target="_blank" rel="noopener" class="docs-link">API 文档 ↗</a></div></header>
      <div v-if="error" class="toast error" role="alert">{{ error }}<button aria-label="关闭错误提示" @click="error=''">×</button></div><div v-if="info" class="toast success" role="status">{{ info }}<button aria-label="关闭提示" @click="info=''">×</button></div>
      <template v-if="screen==='workbench'">
        <section v-if="!task" class="create-view"><div class="intro"><span class="eyebrow">ONE IDEA, TWO CHANNELS</span><h2>今天，想把哪个知识点讲明白？</h2><p>先策划选题，再审核长文，最后生成小红书卡片与公众号文章。</p></div><form class="panel create-form" @submit.prevent="create"><div class="section-heading"><h3>创作简报</h3><span class="pill">小红书 × 微信公众号</span></div><label>主题方向<textarea v-model="form.brief" rows="3" required maxlength="2000" placeholder="例如：用一个最小案例，讲清楚 LangGraph 的人工审核与断点恢复。"></textarea></label><div class="form-grid"><label>课程方向<select v-model="form.course_category"><option>AI应用开发</option><option>AI训练师</option></select></label><label>目标读者<input v-model="form.target_audience" required maxlength="200"></label></div><label>内容模板</label><div class="template-options"><button v-for="option in [{id:'tutorial',name:'实操教程',text:'概念 → 步骤 → 小练习'},{id:'comparison',name:'技术对比',text:'差异 → 取舍 → 适用场景'},{id:'checklist',name:'知识清单',text:'关键点 → 检查项 → 总结'}]" :key="option.id" type="button" :class="{chosen:form.content_template===option.id}" @click="form.content_template=option.id"><strong>{{ option.name }}</strong><span>{{ option.text }}</span></button></div><div class="form-grid three"><label>候选选题<select v-model.number="form.topic_count"><option v-for="n in [3,4,5]" :key="n" :value="n">{{ n }} 个</option></select></label><label>知识卡片<select v-model.number="form.card_count"><option v-for="n in [3,4,5]" :key="n" :value="n">{{ n }} 张</option></select></label><label>视觉主题<select v-model="form.theme"><option value="clean">清爽知识卡</option><option value="dark">深色技术卡</option></select></label></div><label>交付渠道<select v-model="form.workflow_template"><option value="xhs_wechat">小红书 + 公众号</option><option value="xhs_only">只生成小红书图文</option><option value="wechat_only">只生成公众号文章</option></select></label><label v-if="form.reviewer_ids.length" class="inline-check"><input v-model="form.review_topics" type="checkbox">选题也经过组长 / 总监逐级审核</label><div v-if="reviewers.length" class="form-grid"><label>追加一级审核<select :value="form.reviewer_ids[0]||''" @change="form.reviewer_ids=$event.target.value?[$event.target.value]:[]"><option value="">只由我审核</option><option v-for="r in reviewers.filter(r=>r.id!==user.id)" :key="r.id" :value="r.id">{{r.username}} · {{r.role}}</option></select></label><label v-if="form.reviewer_ids[0]">追加总监终审<select :value="form.reviewer_ids[1]||''" @change="form.reviewer_ids=$event.target.value?[form.reviewer_ids[0],$event.target.value]:[form.reviewer_ids[0]]"><option value="">不追加</option><option v-for="r in reviewers.filter(r=>r.id!==user.id&&r.id!==form.reviewer_ids[0]&&['director','admin'].includes(r.role))" :key="r.id" :value="r.id">{{r.username}}</option></select></label></div><button type="button" class="text-button" @click="advanced=!advanced">{{ advanced?'−':'＋' }} 参考资料与编辑要求</button><div v-if="advanced"><label>本次参考资料<textarea v-model="sourceText" rows="4" maxlength="4000" placeholder="粘贴已核实的课程说明、案例或技术资料。也会检索素材库中相关内容。"></textarea></label><label>编辑要求<textarea v-model="form.editor_notes" rows="3" maxlength="4000" placeholder="例如：少用术语，步骤要可验证，不做就业或收入承诺。"></textarea></label></div><div class="create-footer"><span>选题生成后，会停下来等你选择。</span><button class="primary" :disabled="busy||!form.brief.trim()">{{ busy?'正在创建…':'生成候选选题 →' }}</button></div></form><p class="footnote" v-if="capabilities.demo_mode">当前为固定演示样稿，用于体验流程。真实生成需在本地 .env 配置模型接口。</p></section>
        <template v-else><section class="workflow-strip"><div v-for="(label,index) in ['创作简报','人工选题','长文审核','图文加工','交付完成']" :key="label" :class="['workflow-step',{complete:currentStep>index,current:currentStep===index}]"><span>{{ currentStep>index?'✓':String(index+1).padStart(2,'0') }}</span><strong>{{ label }}</strong></div></section><div class="task-meta"><span>{{ task.input.course_category }} · {{ task.input.target_audience }}</span><span class="pill">{{ statusNames[task.status] }}</span><details><summary>会话详情</summary><div class="session-settings"><label>会话名称<input v-model="rename" maxlength="200"></label><button @click="saveName">保存名称</button><code>{{ task.thread_id }}</code></div></details></div>
          <section v-if="task.status==='FAILED'" class="panel failure-panel"><h2>本次操作需要处理</h2><p>{{ task.last_error }}</p><p class="muted">已保存的文案与断点仍然保留。检查本地模型配置后，可以从断点继续。</p><button class="primary" :disabled="busy" @click="action('retry')">从断点重试</button><button v-if="task.state.xhs_pack" :disabled="busy" @click="action('rerender',{})">重新生成卡片</button></section>
          <section v-if="isRunning" class="panel generating"><div class="generating-heading"><span class="spinner"></span><div><h2>{{ nodeNames[stage]||'正在准备创作任务' }}</h2><p class="muted">可以切换会话，任务进度会保存在本地数据库。</p></div></div><pre v-if="streamingText" class="streaming-text">{{ streamingText }}<span class="cursor">▌</span></pre><div v-else class="skeletons"><i></i><i></i><i></i></div></section>
          <section v-if="task.status==='WAITING_TOPIC_SELECTION'" class="panel"><div class="section-heading"><div><span class="eyebrow">EDITORIAL PLANNING</span><h2>从一个值得讲的选题开始</h2></div><span class="muted">选择 1 个选题继续</span></div><div class="topic-list"><button v-for="(topic,index) in task.state.candidate_topics" :key="topic.id" :class="['topic-card',{chosen:selected===topic.id}]" @click="selected=topic.id"><span class="topic-number">{{ String(index+1).padStart(2,'0') }}</span><div><h3>{{ topic.title }}</h3><p>{{ topic.angle }}</p><div class="topic-value">读者收获 · {{ topic.audience_value }}</div><small>选题依据 · {{ topic.evidence }}</small></div><span class="radio-mark">{{ selected===topic.id?'●':'○' }}</span></button></div><div class="actions"><button :disabled="busy" @click="action('regenerate-topics')">换一组选题</button><button @click="newTask">重新填写简报</button><button class="primary" :disabled="!selected||busy" @click="selectTopic">确认选题，生成长文 →</button></div></section>
          <p v-if="task.status==='WAITING_ARTICLE_REVIEW'" class="review-notice">第 {{(task.state.pending_review?.review_index||0)+1}} / {{task.state.pending_review?.review_total||1}} 级审核 · {{canReview?'等待你审核':'等待 '+(task.state.pending_review?.reviewer?.username||'指定审核人')+' 审核'}}</p><TopicReviewPanel v-if="task.status==='WAITING_TOPIC_REVIEW'" :task="task" :busy="busy" :can-review="canReview" @review="(decision,feedback)=>action('review-topic',{interrupt_id:task.interrupt_id,topic_round:task.state.topic_round||0,decision,feedback,operator:user.username})"/><ArticleEditor v-if="task.status==='WAITING_ARTICLE_REVIEW'" :article="task.state.review_article_candidate?.title?task.state.review_article_candidate:task.state.article_draft" :version="task.state.article_version" :busy="busy||!canReview" @approve="value=>review('approved',value)" @reject="value=>review('rejected',value)"/>
          <AssetGallery v-if="task.status==='READY'||task.status==='FAILED'&&task.state.xhs_pack?.slides" :task="task" :can-edit="task.owner_id===user.id" @rerender="body=>action('rerender',body)" @error="message=>error=message"/>
          <RatingPanel v-if="task.status==='READY'&&task.owner_id===user.id" :task="task" @error="message=>error=message" @saved="safe(loadSessions)"/><PerformanceFeedback v-if="task.status==='READY'&&task.owner_id===user.id" :task-id="task.id" @error="message=>error=message"/>
          <section class="panel detail-panel"><div class="detail-tabs"><button v-for="tab in [{id:'progress',name:'执行记录'},{id:'metrics',name:'模型调用'},{id:'history',name:'历史检查点'}]" :key="tab.id" :class="{active:detailTab===tab.id}" @click="detailTab=tab.id">{{ tab.name }}</button></div><div v-if="detailTab==='progress'" class="timeline"><p v-if="!timeline.length" class="muted">当前状态已恢复。新的执行过程会显示在这里。</p><div v-for="event in timeline" :key="event.id"><i></i><strong>{{ nodeNames[event.data.node]||event.data.nodes?.map(n=>nodeNames[n]||n).join('、')||statusNames[event.data.status]||'工作流' }}</strong><span>{{ event.type==='node_started'?'开始执行':event.type==='failed'?'执行失败':event.type==='state_changed'?'状态已保存':'执行完成' }}</span><small v-if="event.data.duration_ms!=null">{{ (event.data.duration_ms/1000).toFixed(2) }}s</small></div></div><div v-if="detailTab==='metrics'"><div class="metric-grid"><div><small>模型调用（含图片）</small><strong>{{ metrics.summary.calls||0 }}</strong></div><div><small>输入 / 输出 Token</small><strong>{{ metrics.summary.input_tokens??'—' }} / {{ metrics.summary.output_tokens??'—' }}</strong></div><div><small>估算费用 · 配置计价单位</small><strong>{{ metrics.summary.estimated_cost?.toFixed(5)??'—' }}</strong></div></div><p class="muted">Token 来自供应商响应；演示模式或缺失用量显示“—”。费用需先配置当前模型单价，统计包含失败重试。</p><div class="table-scroll"><table><thead><tr><th>阶段</th><th>模型</th><th>耗时</th><th>用量来源</th><th>结果</th></tr></thead><tbody><tr v-for="item in metrics.items" :key="item.id"><td>{{ {TopicBatch:'选题',Article:'长文',CardPack:'卡片'}[item.stage]||item.stage }}</td><td>{{ item.model }}</td><td>{{ (item.duration_ms/1000).toFixed(2) }}s</td><td>{{ {mock:'演示',provider:'供应商',unavailable:'未返回',cache:'缓存命中',configured_image_price:'配置单张估价'}[item.usage_source] }}</td><td>{{ item.success?'完成':'失败' }}</td></tr></tbody></table></div></div><div v-if="detailTab==='history'" class="table-scroll"><p class="muted">从历史检查点创建一个新会话继续，原会话与结果保留。</p><table><thead><tr><th>保存时间</th><th>文章版本</th><th>下一阶段</th><th></th></tr></thead><tbody><tr v-for="checkpoint in checkpoints" :key="checkpoint.id"><td>{{ new Date(checkpoint.created_at).toLocaleString('zh-CN') }}</td><td>{{ checkpoint.article_version||'—' }}</td><td>{{ checkpoint.ready?'已完成':checkpoint.next.map(n=>nodeNames[n]||({select_topic:'人工选题',review_article:'人工审稿',review_topic:'选题审核'}[n])||n).join('、')||'已保存' }}</td><td><button :disabled="busy||isRunning" @click="forkCheckpoint(checkpoint)">从此版本创建副本</button></td></tr></tbody></table></div></section>
        </template>
      </template>
      <template v-else-if="screen==='library'"><KnowledgePanel @error="message=>error=message"/></template>
      <template v-else-if="screen==='prompts'"><PromptLab :demo-mode="capabilities.demo_mode" @error="message=>error=message"/></template>
      <template v-else-if="screen==='account'"><AccountPanel :user="user" @error="message=>error=message" @updated="value=>user=value"/></template>
      <template v-else><div class="intro compact"><h2>看见每一步创作的进展。</h2><p>以下统计来自本地任务与审核记录，不代表小红书平台实时数据。</p></div><div class="overview-grid"><div v-for="metric in [{name:'累计创作',value:dashboard.tasks||0},{name:'图文就绪',value:dashboard.ready||0},{name:'待人工审稿',value:dashboard.waiting_review||0},{name:'累计重写',value:dashboard.revisions||0},{name:'选题选择率',value:dashboard.selection_rate==null?'—':(dashboard.selection_rate*100).toFixed(1)+'%'},{name:'审稿驳回率',value:dashboard.review_rejection_rate==null?'—':(dashboard.review_rejection_rate*100).toFixed(1)+'%'},{name:'平均修订次数',value:dashboard.average_revisions?.toFixed(2)??'—'},{name:'平均满意度',value:dashboard.average_rating?.toFixed(2)??'—'}]" :key="metric.name" class="panel"><small>{{ metric.name }}</small><strong>{{ metric.value }}</strong></div></div><section class="panel"><h3>创作漏斗</h3><div class="metric-grid"><div v-for="(value,key) in dashboard.funnel||{}" :key="key"><small>{{{created:'创建',topics:'有候选题',selected:'已选题',article:'有长文',approved:'已定稿',ready:'交付就绪'}[key]}}</small><strong>{{value}}</strong></div></div><h3>按长文提示词版本比较人工评分</h3><table><thead><tr><th>版本摘要</th><th>样本量</th><th>平均分 / 5</th></tr></thead><tbody><tr v-for="r in dashboard.prompt_ratings||[]" :key="r.digest"><td>{{r.digest.slice(0,12)}}</td><td>{{r.count}}</td><td>{{r.average.toFixed(2)}}</td></tr></tbody></table><p class="muted">样本量与受众会影响评分，不能直接证明某版本更好。</p></section><section class="panel"><h3>把内容表现带回选题</h3><p class="muted">在已完成的内容下录入阅读、点赞、收藏和评论累计数据。新任务会参考同课程的历史样本，数据不会被描述成平台全局趋势。</p><button @click="screen='workbench'">返回创作工作台</button></section></template>
      <footer class="page-footer">知行 · AI 内容工作室 <span>本地运行 · 人工确认 · 多渠道交付</span></footer>
    </main>
  </div>
</template>
